import{_ as t,c as d,o as a,ae as r}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse(`{"title":"List EU Withdrawals","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-eu-withdrawals","title":"List Own EU Withdrawals","description":"Retrieve a paginated list of the authenticated customer's own EU right-of-withdrawal declarations, newest first.","query":"query EuWithdrawals(\\n  $first: Int\\n  $after: String\\n) {\\n  euWithdrawals(\\n    first: $first\\n    after: $after\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        _id\\n        uuid\\n        orderId\\n        orderIncrementId\\n        isGuest\\n        customerEmail\\n        status\\n        reasonText\\n        receivedAt\\n        confirmationSentAt\\n        declinedAt\\n        declinedReason\\n        refundedAt\\n        refundNote\\n        createdAt\\n        updatedAt\\n      }\\n    }\\n    pageInfo {\\n      startCursor\\n      endCursor\\n      hasNextPage\\n      hasPreviousPage\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"after\\": null\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"euWithdrawals\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MQ==\\",\\n          \\"node\\": {\\n            \\"_id\\": 7,\\n            \\"uuid\\": \\"b2f1c0de-5a2e-4d7a-9f2e-3c1a2b4d5e6f\\",\\n            \\"orderId\\": 12,\\n            \\"orderIncrementId\\": \\"000000012\\",\\n            \\"isGuest\\": false,\\n            \\"customerEmail\\": \\"jane@example.com\\",\\n            \\"status\\": \\"received\\",\\n            \\"reasonText\\": \\"Changed my mind.\\",\\n            \\"receivedAt\\": \\"2026-07-20T09:00:00+00:00\\",\\n            \\"confirmationSentAt\\": \\"2026-07-20T09:00:05+00:00\\",\\n            \\"declinedAt\\": null,\\n            \\"declinedReason\\": null,\\n            \\"refundedAt\\": null,\\n            \\"refundNote\\": null,\\n            \\"createdAt\\": \\"2026-07-20T09:00:00+00:00\\",\\n            \\"updatedAt\\": \\"2026-07-20T09:00:05+00:00\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"startCursor\\": \\"MQ==\\",\\n        \\"endCursor\\": \\"MQ==\\",\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/eu-withdrawal/queries/list-eu-withdrawals.md","filePath":"api/graphql-api/shop/eu-withdrawal/queries/list-eu-withdrawals.md"}`),o={name:"api/graphql-api/shop/eu-withdrawal/queries/list-eu-withdrawals.md"};function n(i,e,s,c,l,u){return a(),d("div",null,e[0]||(e[0]=[r('<h1 id="list-eu-withdrawals" tabindex="-1">List EU Withdrawals <a class="header-anchor" href="#list-eu-withdrawals" aria-label="Permalink to &quot;List EU Withdrawals&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>euWithdrawals</code> query returns a paginated list of the authenticated customer&#39;s <strong>own</strong> EU right-of-withdrawal declarations. Declarations are always scoped to the logged-in customer — you can never see another customer&#39;s declarations. Results are ordered newest first.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>❌ No</td><td>Number of items to return (forward pagination).</td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>❌ No</td><td>Cursor for forward pagination. Use <code>endCursor</code> from a previous response.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>edges</code></td><td><code>[EuWithdrawalEdge!]</code></td><td>Array of declaration edges with cursor and node.</td></tr><tr><td><code>edges.cursor</code></td><td><code>String!</code></td><td>Cursor for this edge, used in pagination.</td></tr><tr><td><code>edges.node</code></td><td><code>EuWithdrawal!</code></td><td>The withdrawal declaration object.</td></tr><tr><td><code>edges.node._id</code></td><td><code>Int!</code></td><td>Numeric declaration ID.</td></tr><tr><td><code>edges.node.uuid</code></td><td><code>String!</code></td><td>Stable public identifier for the declaration.</td></tr><tr><td><code>edges.node.orderId</code></td><td><code>Int!</code></td><td>Numeric ID of the order the withdrawal applies to.</td></tr><tr><td><code>edges.node.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>edges.node.isGuest</code></td><td><code>Boolean!</code></td><td>Whether the declaration was filed on a guest order.</td></tr><tr><td><code>edges.node.customerEmail</code></td><td><code>String!</code></td><td>Email address tied to the declaration.</td></tr><tr><td><code>edges.node.status</code></td><td><code>String!</code></td><td>Declaration status: <code>received</code>, <code>declined</code>, <code>refunded</code>.</td></tr><tr><td><code>edges.node.reasonText</code></td><td><code>String</code></td><td>The reason the shopper supplied, or <code>null</code>.</td></tr><tr><td><code>edges.node.receivedAt</code></td><td><code>DateTime</code></td><td>Timestamp when the declaration was received.</td></tr><tr><td><code>edges.node.confirmationSentAt</code></td><td><code>DateTime</code></td><td>Timestamp when the confirmation email was sent, or <code>null</code>.</td></tr><tr><td><code>edges.node.declinedAt</code></td><td><code>DateTime</code></td><td>Timestamp when the withdrawal was declined, or <code>null</code>.</td></tr><tr><td><code>edges.node.declinedReason</code></td><td><code>String</code></td><td>Reason the store declined the withdrawal, or <code>null</code>.</td></tr><tr><td><code>edges.node.refundedAt</code></td><td><code>DateTime</code></td><td>Timestamp when the order was refunded, or <code>null</code>.</td></tr><tr><td><code>edges.node.refundNote</code></td><td><code>String</code></td><td>Note attached to the refund, or <code>null</code>.</td></tr><tr><td><code>edges.node.createdAt</code></td><td><code>DateTime!</code></td><td>Declaration creation timestamp.</td></tr><tr><td><code>edges.node.updatedAt</code></td><td><code>DateTime!</code></td><td>Declaration last update timestamp.</td></tr><tr><td><code>pageInfo</code></td><td><code>PageInfo!</code></td><td>Pagination metadata.</td></tr><tr><td><code>pageInfo.startCursor</code></td><td><code>String</code></td><td>Cursor for the first item in the page.</td></tr><tr><td><code>pageInfo.endCursor</code></td><td><code>String</code></td><td>Cursor for the last item in the page.</td></tr><tr><td><code>pageInfo.hasNextPage</code></td><td><code>Boolean!</code></td><td>Whether more pages exist forward.</td></tr><tr><td><code>pageInfo.hasPreviousPage</code></td><td><code>Boolean!</code></td><td>Whether more pages exist backward.</td></tr><tr><td><code>totalCount</code></td><td><code>Int!</code></td><td>Total number of the customer&#39;s declarations.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/eu-withdrawal/queries/view-eu-withdrawal.html">View EU Withdrawal</a></li><li><a href="/api/graphql-api/shop/eu-withdrawal/mutations/create-eu-withdrawal.html">File a Withdrawal</a></li><li><a href="/api/graphql-api/shop/eu-withdrawal/">EU Withdrawal Overview</a></li></ul>',11)]))}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
